<script setup lang="ts">
import { computed, inject, onBeforeUnmount, onMounted, provide, ref, watch } from 'vue';
import { useRoute, useRouter, type LocationQueryRaw } from 'vue-router';
import { useQueryClient } from '@tanstack/vue-query';
import { ArrowLeft, BookOpen, ChevronDown, Database, Files, FolderGit2, GitBranch, GitCommitHorizontal, GitPullRequest, Globe2, LayoutPanelLeft, LoaderCircle, Lock, Package, Settings2, Users, FileArchive } from 'lucide-vue-next';
import type { BranchItem, Capabilities, RepoSummary, RepositoryPermissions, RepositorySettingsState } from '@oxen/shared';
import type { ProjectLabelState } from '../../../../packages/shared/src/project-label-types';
import { ApiError, repoBase, request } from '../api';
import { useAppStore } from '../stores/app';
import {lazyRepositoryPanel} from '../lazy-repository-panel';
const FileBrowser=lazyRepositoryPanel('原始文件',()=>import('../components/FileBrowser.vue'));
const CommitPanel=lazyRepositoryPanel('提交历史',()=>import('../components/CommitPanel.vue'));
const BranchPanel=lazyRepositoryPanel('分支',()=>import('../components/BranchPanel.vue'));
const WorkspacePanel=lazyRepositoryPanel('工作区',()=>import('../components/WorkspacePanel.vue'));
const SettingsPanel=lazyRepositoryPanel('项目设置',()=>import('../components/SettingsPanel.vue'));
const DatasetWorkbench=lazyRepositoryPanel('数据编辑',()=>import('../components/DatasetWorkbench.vue'));
import DatasetOverview from '../components/DatasetOverview.vue';
const TaskPanel=lazyRepositoryPanel('任务与复核',()=>import('../components/TaskPanel.vue'));
import TaskContextBanner from '../components/TaskContextBanner.vue';
const MergeRequestPanel=lazyRepositoryPanel('合并请求',()=>import('../components/MergeRequestPanel.vue'));
const ReleasesPanel=lazyRepositoryPanel('发布',()=>import('../components/ReleasesPanel.vue'));

const ArchiveDiff=lazyRepositoryPanel('ZIP 内容差异',()=>import('../components/ArchiveDiff.vue'));
const MergeResolutionPanel=lazyRepositoryPanel('冲突裁决',()=>import('../components/MergeResolutionPanel.vue'));
import BranchDatasetLabels from '../components/BranchDatasetLabels.vue';
import {withProjectKeywords} from '../project-label-chips';
const route=useRoute(),router=useRouter(),app=useAppStore(),cache=useQueryClient();
const base=computed(()=>repoBase(String(route.params.namespace),String(route.params.repo)));
const repo=ref<RepoSummary>(),branches=ref<BranchItem[]>([]),branch=ref(''),error=ref(''),revision=ref(0),loading=ref(true),readCommit=ref(''),sampleCount=ref<number>();
const branchSelector=ref<HTMLSelectElement|null>(null),developerMenu=ref<HTMLDetailsElement|null>(null);
const datasetLabelsOpen=ref(false),projectLabels=ref<ProjectLabelState>(),catalogError=ref('');
const projectTags=computed(()=>withProjectKeywords((projectLabels.value?.columns??[]).flatMap(column=>{const raw=projectLabels.value?.values[column.id],values=Array.isArray(raw)?raw:raw?[raw]:[];return values.map(value=>({key:column.id+':'+value,label:column.options?.find(option=>option.value===value)?.displayName??value,name:column.name}));}),projectLabels.value?.keywords??[]));
const workbench=ref<{refresh:()=>Promise<boolean>;hasUnsaved:boolean}>();
const permissions=ref<RepositoryPermissions>({read:false,write:false,admin:false,role:null}),errorStatus=ref(0);
provide('repositoryPermissions',computed(()=>permissions.value));provide('repositoryBranches',computed(()=>branches.value));
const openIdentity=inject<()=>void>('openIdentityDialog',()=>{});
const roleName=computed(()=>( {owner:'实例管理员',admin:'项目管理员',lead:'数据集负责人',editor:'编辑与标注',annotator:'标注人员',reviewer:'复核人员',viewer:'只读协作者',guest:'公开访客'} as Record<string,string>)[permissions.value.role || ''] || '无权限');
const historical=computed(()=>typeof route.query.commit==='string'&&!!route.query.commit);
const reference=computed(()=>historical.value?String(route.query.commit):branch.value);
const missingBranch=computed(()=>!!branch.value&&!branches.value.some(item=>item.name===branch.value));
const remoteHead=computed(()=>branches.value.find(item=>item.name===branch.value)?.commitId??'');
const hasNewHead=computed(()=>!historical.value&&!!readCommit.value&&!!remoteHead.value&&readCommit.value!==remoteHead.value);
const repositoryCapabilities=computed<Capabilities|undefined>(()=>app.status?({...app.status.capabilities,write:app.status.capabilities.write&&permissions.value.write&&!historical.value,cli:app.status.capabilities.cli&&permissions.value.write&&!historical.value,workspaces:app.status.capabilities.workspaces&&permissions.value.write&&!historical.value,metadata:app.status.capabilities.metadata&&permissions.value.admin,reasons:{...app.status.capabilities.reasons,...(!permissions.value.write?{write:'当前身份只有读取权限。',workspaces:'当前身份只有读取权限。',cli:'当前身份没有写入权限。'}:{})}}):undefined);
const primaryTabs=[{id:'overview',label:'概览',icon:BookOpen},{id:'table',label:'数据编辑',icon:Database},{id:'tasks',label:'任务与复核',icon:Users},{id:'versions',label:'版本与合并',icon:GitPullRequest},{id:'releases',label:'Releases',icon:Package},{id:'settings',label:'设置',icon:Settings2}];
const versionTabs=[{id:'commits',label:'提交历史',icon:GitCommitHorizontal},{id:'branches',label:'分支',icon:GitBranch},{id:'merges',label:'合并请求',icon:GitPullRequest},{id:'resolve',label:'冲突裁决',icon:GitPullRequest},{id:'archive-diff',label:'ZIP 内容差异',icon:FileArchive}];
const advancedTabs=[{id:'files',label:'原始文件',icon:Files},{id:'workspaces',label:'工作区',icon:LayoutPanelLeft}];
const known=[...primaryTabs,...versionTabs,...advancedTabs].map(item=>item.id);
const tab=computed(()=>known.includes(String(route.params.tab))?String(route.params.tab):'overview');
const isVersions=computed(()=>tab.value==='versions'||versionTabs.some(item=>item.id===tab.value));
const currentAdvanced=computed(()=>advancedTabs.find(item=>item.id===tab.value));
let generation=0,initializedBase='',poll:ReturnType<typeof setInterval>|undefined;
function size(value=0){return value<1024?value+' B':value<1024**2?(value/1024).toFixed(1)+' KB':value<1024**3?(value/1024**2).toFixed(1)+' MB':(value/1024**3).toFixed(2)+' GB';}
function updated(value?:string){return value&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleDateString('zh-CN',{month:'short',day:'numeric'}):'—';}
function closeDeveloperMenu(){if(developerMenu.value)developerMenu.value.open=false;}
function outsideDeveloperMenu(event:MouseEvent){if(developerMenu.value?.open&&!developerMenu.value.contains(event.target as Node))closeDeveloperMenu();}
watch(()=>route.fullPath,closeDeveloperMenu);
function routeFor(id:string,query:LocationQueryRaw={}){return {path:'/repos/'+encodeURIComponent(String(route.params.namespace))+'/'+encodeURIComponent(String(route.params.repo))+'/'+id,query};}
function tabLink(id:string){const query:LocationQueryRaw={branch:branch.value};if(['overview','table','files'].includes(id)&&historical.value)query.commit=String(route.query.commit);if(id==='files'&&typeof route.query.file==='string')query.file=route.query.file;return routeFor(id,query);}
async function load(){const current=++generation,location=base.value;loading.value=true;error.value='';errorStatus.value=0;try{
  const [summary,items,state]=await Promise.all([request<RepoSummary>(location),request<BranchItem[]>(location+'/branches'),request<RepositorySettingsState>(location+'/settings')]);if(current!==generation)return;
  repo.value=summary;branches.value=items;permissions.value=state.permissions??{read:false,write:false,admin:false,role:null};
  const requested=typeof route.query.branch==='string'?route.query.branch:'';
  if(initializedBase!==location)branch.value=requested||summary.defaultBranch||items.find(item=>item.isDefault)?.name||items[0]?.name||'main';else if(requested)branch.value=requested;
  initializedBase=location;if(sampleCount.value===undefined&&!historical.value&&branch.value===summary.defaultBranch&&summary.sampleCountCommitId===items.find(item=>item.name===branch.value)?.commitId&&typeof summary.sampleCount==='number')sampleCount.value=summary.sampleCount;revision.value++;
}catch(cause){if(current===generation){error.value=(cause as Error).message;errorStatus.value=cause instanceof ApiError?cause.status:0;repo.value=undefined;permissions.value={read:false,write:false,admin:false,role:null};}}finally{if(current===generation)loading.value=false;}}
async function refreshBranches(){const location=base.value;try{const value=await request<BranchItem[]>(location+'/branches');if(base.value===location){const previousMain=branches.value.find(item=>item.name==='main')?.commitId,nextMain=value.find(item=>item.name==='main')?.commitId;branches.value=value;if(previousMain!==nextMain&&projectLabels.value?.commitId!==nextMain)void loadProjectLabels();}}catch(cause){if(cause instanceof ApiError&&[401,403].includes(cause.status)){error.value=cause.message;errorStatus.value=cause.status;repo.value=undefined;permissions.value={read:false,write:false,admin:false,role:null};}}}
watch(base,()=>{repo.value=undefined;branches.value=[];branch.value='';readCommit.value='';sampleCount.value=undefined;permissions.value={read:false,write:false,admin:false,role:null};initializedBase='';void load();},{immediate:true});
watch(()=>route.query.branch,value=>{const name=String(value??'');if(name&&name!==branch.value){branch.value=name;readCommit.value='';sampleCount.value=undefined;if(!historical.value&&name===repo.value?.defaultBranch&&repo.value?.sampleCountCommitId===branches.value.find(item=>item.name===name)?.commitId&&typeof repo.value?.sampleCount==='number')sampleCount.value=repo.value.sampleCount;}});
watch(()=>route.query.commit,()=>{readCommit.value='';sampleCount.value=undefined;});
watch(()=>route.params.tab,value=>{if(value==='annotations'||value==='query')void router.replace(routeFor('table',{...route.query}));},{immediate:true});
async function changeBranch(name:string){if(name===branch.value||!branches.value.some(item=>item.name===name))return;const query:LocationQueryRaw={...route.query,branch:name};delete query.commit;delete query.task;delete query.sample;delete query.release;try{await router.replace({query});}finally{if(branchSelector.value)branchSelector.value.value=branch.value;}}
function loaded(value:{commitId:string;totalRows:number}){readCommit.value=value.commitId;sampleCount.value=value.totalRows;}
async function saved(value:{commitId:string;totalRows:number}){loaded(value);await refreshBranches();void cache.invalidateQueries({queryKey:['repos']});}
async function changed(){await load();await loadProjectLabels();void cache.invalidateQueries({queryKey:['repos']});}
async function workflowChanged(){await changed();await workbench.value?.refresh();}
function openTask(taskId:string,name:string,rowId?:string){void router.push(routeFor('table',{branch:name,task:taskId,...(rowId?{sample:rowId}:{})}));}
function openVersion(commitId:string){void router.push(routeFor('table',{branch:branch.value,commit:commitId}));}
function compareArchive(filename:string){void router.push(routeFor('archive-diff',{branch:branch.value,path:filename}));}
function resolveFromRequest(source:string,target:string){void router.push(routeFor('resolve',{branch:branch.value,source,target}));}
async function refreshDataset(){if(tab.value==='table')await workbench.value?.refresh();else{readCommit.value='';await load();}}
let catalogGeneration=0;
async function loadProjectLabels(reset=false){const current=++catalogGeneration;if(reset)projectLabels.value=undefined;catalogError.value='';if(!permissions.value.read){projectLabels.value=undefined;return;}try{const result=await request<ProjectLabelState>(base.value+'/project-labels');if(current===catalogGeneration)projectLabels.value=result;}catch(cause){if(current===catalogGeneration){projectLabels.value=undefined;catalogError.value=(cause as Error).message;}}}
watch([base,()=>permissions.value.read,()=>app.status?.identity?.id],()=>{void loadProjectLabels(true);},{immediate:true});
async function datasetLabelsChanged(_commitId:string){await loadProjectLabels();await refreshBranches();void cache.invalidateQueries({queryKey:['repos']});}
function configureProjectLabels(){void router.push(routeFor('settings',{branch:'main'}));}
function createMainBranch(){void router.push(routeFor('branches',{branch:branches.value.find(item=>item.name==='main')?.name??branches.value[0]?.name??branch.value}));}
onMounted(()=>{document.addEventListener('click',outsideDeveloperMenu);poll=setInterval(()=>void refreshBranches(),15000);});
onBeforeUnmount(()=>{generation++;catalogGeneration++;clearInterval(poll);document.removeEventListener('click',outsideDeveloperMenu);});
</script>
<template>
<div class="page repository-page" :class="{'repository-wide':tab==='table'}">
  <section class="repository-masthead"><div class="repository-heading"><div class="repository-heading-main"><div class="project-location"><RouterLink to="/">项目</RouterLink><span>/</span><span>{{route.params.namespace}}</span></div><div class="repository-title-row"><FolderGit2 :size="25" class="project-icon"/><h1>{{repo?.displayName||route.params.repo}}</h1><span class="badge visibility-badge"><Globe2 v-if="repo?.visibility==='public'" :size="11"/><Lock v-else :size="11"/>{{repo?.visibility==='public'?'公开':repo?.visibility==='private'?'私有':'本地项目'}}</span></div><p class="repository-description">{{repo?.description||'在分支中编辑与标注样本，复核合并后发布可下载的数据集版本。'}}</p></div><div class="repository-actions"><RouterLink :to="tabLink('settings')" class="btn manage-project"><Settings2 :size="15"/>管理项目</RouterLink><details ref="developerMenu" class="developer-tools"><summary :class="{selected:!!currentAdvanced}">高级工具<ChevronDown :size="14"/></summary><nav aria-label="高级工具"><RouterLink v-for="item in advancedTabs" :key="item.id" :to="tabLink(item.id)" :class="{active:tab===item.id}"><component :is="item.icon" :size="16"/>{{item.label}}</RouterLink></nav></details></div></div><div class="repository-metadata"><div><span>命名空间</span><strong>{{route.params.namespace}}</strong></div><div><span>样本数</span><strong>{{sampleCount===undefined?'—':sampleCount.toLocaleString()}}</strong></div><div><span>存储</span><strong>{{repo?size(repo.size):'—'}}</strong></div><div><span>最近更新</span><strong>{{updated(repo?.updatedAt)}}</strong></div><div class="metadata-role"><span>你的权限</span><strong>{{loading&&!repo?'—':roleName}}</strong></div></div></section>
  <div v-if="error" class="error-state repository-error" role="alert"><div><strong v-if="[401,403].includes(errorStatus)">当前身份无法访问这个项目</strong><p>{{error}}</p></div><button class="btn" @click="load">重试</button><button v-if="[401,403].includes(errorStatus)" class="btn" @click="openIdentity">登录 / 切换身份</button></div>
  <div v-else-if="loading&&!repo" class="empty" role="status"><LoaderCircle class="spin" :size="25"/><p>正在读取项目…</p></div>
  <template v-else-if="repo">
    <div class="branch-dataset-tags"><span>项目标签</span><template v-if="projectLabels"><span v-for="item in projectTags.slice(0,3)" :key="item.key" class="badge" :class="{'project-keyword':item.kind==='keyword'}" :title="item.kind==='keyword'?'项目关键词':item.name">{{item.label}}</span><span v-if="projectTags.length>3" :title="projectTags.slice(3).map(item=>item.label).join('、')">+{{projectTags.length-3}}</span><span v-if="!projectTags.length">{{projectLabels.state==='missing-main'?'尚无 main 分支':projectLabels.state==='unconfigured'?'尚未配置标签模板':'尚未填写'}}</span></template><span v-else>{{catalogError?'标签读取失败':'正在读取标签…'}}</span><button v-if="projectLabels?.capabilities.edit" class="btn" @click="datasetLabelsOpen=true">编辑标签</button><button v-else class="btn btn-ghost" @click="datasetLabelsOpen=true">查看标签</button></div>
    <div class="repository-resource-nav"><label class="branch-selector"><GitBranch :size="15"/><select ref="branchSelector" :value="branch" aria-label="当前分支" @change="changeBranch(($event.target as HTMLSelectElement).value)"><option v-for="item in branches" :key="item.name" :value="item.name">{{item.name}}</option><option v-if="missingBranch" :value="branch">{{branch}}（不存在）</option></select></label><nav class="resource-tabs" aria-label="项目功能"><RouterLink v-for="item in primaryTabs" :key="item.id" :to="tabLink(item.id)" :class="{active:tab===item.id||item.id==='versions'&&isVersions}"><component :is="item.icon" :size="15"/>{{item.label}}</RouterLink></nav></div>
    <div v-if="historical" class="repository-version-strip historical"><Lock :size="13"/><span>固定提交 · 只读预览</span><code>{{String(route.query.commit).slice(0,12)}}</code><button class="btn btn-ghost" @click="router.push(routeFor('table',{branch}))">返回工作分支</button></div>
    <div v-else-if="readCommit&&['overview','table'].includes(tab)" class="repository-version-strip"><GitCommitHorizontal :size="13"/><span>当前读取</span><code>{{readCommit.slice(0,12)}}</code><span v-if="hasNewHead" class="new-head">分支已有新提交</span><button v-if="hasNewHead" class="btn btn-ghost" @click="refreshDataset">刷新查看</button></div>
    <p v-if="missingBranch&&!['releases','settings','tasks'].includes(tab)" class="error-state" role="alert">所选分支不存在。请选择已有分支；系统没有切换到其他版本。</p>
    <div v-if="!permissions.write" class="repository-readonly"><Lock :size="14"/><span><strong>{{roleName}}</strong> · 可以浏览授权内容，编辑与标注按项目角色开放。</span></div>
    <div v-if="currentAdvanced" class="advanced-return"><RouterLink :to="tabLink('overview')"><ArrowLeft :size="14"/>返回数据集</RouterLink><span>高级工具 / {{currentAdvanced.label}}</span></div>
    <div class="repository-content">
      <DatasetOverview v-if="tab==='overview'" :key="'overview'+revision" :base="base" :branch="reference" :project-labels="projectLabels" :project-label-error="catalogError" @loaded="loaded" @edit-labels="datasetLabelsOpen=true" @open="id=>router.push(tabLink(id))"/>
      <template v-else-if="tab==='table'"><TaskContextBanner :base="base" :branch="branch" :commit-id="readCommit" :has-unsaved="workbench?.hasUnsaved" @changed="workflowChanged"/><DatasetWorkbench ref="workbench" :base="base" :branch="branch" :latest-commit="remoteHead" @loaded="loaded" @saved="saved" @edit-project-labels="datasetLabelsOpen=true" @compare-archive="compareArchive"/></template>
      <TaskPanel v-else-if="tab==='tasks'" :base="base" :branch="branch" @open="openTask" @changed="changed"/>
      <ReleasesPanel v-else-if="tab==='releases'" :base="base" :branch="branch" @open-version="openVersion"/>
      <template v-else-if="isVersions"><nav class="version-tabs" aria-label="版本协作"><RouterLink v-for="item in versionTabs" :key="item.id" :to="tabLink(item.id)" :class="{active:tab===item.id||(tab==='versions'&&item.id==='commits')}"><component :is="item.icon" :size="14"/>{{item.label}}</RouterLink></nav><CommitPanel v-if="['versions','commits'].includes(tab)" :key="'commits'+branch" :base="base" :branch="branch" :can-restore="permissions.admin" @changed="changed"/><BranchPanel v-else-if="tab==='branches'" :base="base" :branch="branch" :capabilities="repositoryCapabilities" @changed="changed" @branch-change="changeBranch"/><MergeRequestPanel v-else-if="tab==='merges'" :base="base" :branch="branch" @changed="changed" @resolve-conflicts="resolveFromRequest"/><MergeResolutionPanel v-else-if="tab==='resolve'" :base="base" :branch="branch" @changed="changed" @source-updated="refreshBranches"/><ArchiveDiff v-else :base="base" :branch="branch" :path="typeof route.query.path==='string'?route.query.path:''"/></template>
      <FileBrowser v-else-if="tab==='files'" :key="'files'+revision+reference" :base="base" :branch="reference"/>
      <WorkspacePanel v-else-if="tab==='workspaces'" :base="base" :branch="branch" :capabilities="repositoryCapabilities" @changed="changed"/>
      <SettingsPanel v-else-if="tab==='settings'" :base="base" :branch="branch" :capabilities="repositoryCapabilities" @changed="changed"/>
    </div>
    <BranchDatasetLabels v-if="datasetLabelsOpen" :base="base" :can-configure="permissions.capabilities?.['schema.bind']===true" @close="datasetLabelsOpen=false" @changed="datasetLabelsChanged" @configure="configureProjectLabels" @create-main="createMainBranch"/>
  </template>
</div>
</template>
<style scoped>
.repository-wide{max-width:none;width:100%;min-width:0}.repository-wide .repository-content{width:100%;min-width:0;max-width:100%}

.branch-dataset-tags{display:flex;align-items:center;flex-wrap:wrap;gap:8px;font-size:11px;color:var(--muted);margin:-8px 0 20px;padding:10px 0;border-bottom:1px solid var(--line)}.branch-dataset-tags>.btn{margin-left:auto;font-size:11px;min-height:27px}.branch-dataset-tags>.badge{color:var(--accent)}
.branch-dataset-tags>.project-keyword{border-style:dashed;color:var(--muted);background:var(--surface)}
.repository-page{padding-top:30px}.repository-masthead{padding-bottom:26px;border-bottom:1px solid var(--line);margin-bottom:24px}.repository-heading{display:flex;justify-content:space-between;gap:35px}.repository-heading-main{min-width:0;flex:1}.project-location{display:flex;align-items:center;gap:9px;font-size:12px;color:var(--muted);margin-bottom:17px}.project-location>a:hover{color:var(--text)}.project-location>span:nth-child(2){color:var(--subtle)}.repository-title-row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.project-icon{color:#ae9bbd}.repository-title-row h1{font-size:30px;letter-spacing:-.6px;overflow-wrap:anywhere;max-width:100%;font-weight:620}.visibility-badge{padding:2px 7px;background:transparent;border-color:#48484f;border-radius:12px;font-size:10px;margin-left:3px}.repository-description{color:var(--muted);font-size:13px;margin-top:12px;max-width:850px;line-height:1.7}.project-tags{display:flex;gap:6px;flex-wrap:wrap;margin-top:11px}.project-tags>span{border:1px solid #43374f;color:#b99ad9;background:#302637;font-size:11px;padding:1px 7px;border-radius:4px}.repository-actions{display:flex;flex-direction:column;gap:9px;min-width:167px;padding-top:33px}.manage-project{font-size:12px;min-height:34px;background:#303033}.manage-project.selected{border-color:#8557a5;color:var(--accent)}.developer-tools{position:relative}.developer-tools>summary{display:flex;align-items:center;justify-content:center;gap:9px;list-style:none;border:1px solid #414147;border-radius:6px;min-height:33px;font-size:12px;color:var(--muted);background:transparent}.developer-tools>summary:hover,.developer-tools>summary.selected{background:var(--surface-raised);color:var(--text)}.developer-tools>nav{position:absolute;top:calc(100% + 7px);right:0;width:228px;padding:6px;border:1px solid #48464e;background:#252528;border-radius:7px;box-shadow:0 15px 45px #0008;z-index:65}.developer-tools nav>a{display:flex;align-items:center;gap:10px;padding:10px 11px;border-radius:4px;fon